import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const JobSeekerDashboard: React.FC = () => {
    const navigate = useNavigate();
    const [agencyDetails, setAgencyDetails] = useState<any>(null);
    const [jobSeekerDetails, setJobSeekerDetails] = useState<any>(null);
    const [isApproved, setIsApproved] = useState<boolean>(false);

    useEffect(() => {
        const token = localStorage.getItem('token');
        const agency = localStorage.getItem('agencyDetails');
        const jobSeeker = localStorage.getItem('associatedJobSeekers'); // Assuming you have this in local storage

        if (!token) {
            navigate('/login'); 
        }

        if (agency) {
            const parsedAgency = JSON.parse(agency);
            setAgencyDetails(parsedAgency);
            setIsApproved(parsedAgency.isApproved); // Assuming `isApproved` is a field in agency details
        }

        if (jobSeeker) {
            setJobSeekerDetails(JSON.parse(jobSeeker)); // Store job seeker details
        }
    }, [navigate]);

    const handleChatClick = () => {

        navigate('/chat-room');
    };

    return (
        <div className="container mt-5">
            <h1 className="text-center">Job Seeker Dashboard</h1>
            {jobSeekerDetails && (
                <div className="alert alert-info">
                    <h4>Welcome, {jobSeekerDetails.firstName} {jobSeekerDetails.lastName}!</h4>
                </div>
            )}
            <div className="card p-4 mt-3">
                <h2>Your Agency Details</h2>
                {agencyDetails ? (
                    <div>
                        <p><strong>Agency Name:</strong> {agencyDetails.firstName} {agencyDetails.lastName}</p>
                        <p><strong>Email:</strong> {agencyDetails.email}</p>
                        <p><strong>Phone:</strong> {agencyDetails.phone}</p>
                        {isApproved ? (
                            <button onClick={handleChatClick} className="btn btn-primary mt-3">
                                Start Chat
                            </button>
                        ) : (
                            <p className="text-danger mt-3">Your agency is not approved for chat.</p>
                        )}
                    </div>
                ) : (
                    <p>No agency associated with your profile.</p>
                )}
            </div>
        </div>
    );
};

export default JobSeekerDashboard;
